"""Page flow: places measured boxes onto pages and emits drawing operations."""
from __future__ import annotations

from dataclasses import dataclass, replace
from typing import List, Optional

from ..document import Document, Section
from .boxes import (BORDER_DASHES, DestOp, ImageOp, LineBox, LineOp, LinkOp,
                    OutlineOp, Page, ParaBox, RectOp, RowBox, TableBox,
                    TextOp)

SEPARATOR_GAP = 4.0


def _hex(color: Optional[str]) -> Optional[str]:
    """Normalise a VML colour ('#1F497D', 'red') to 'RRGGBB'."""
    if not color:
        return None
    value = color.strip().lstrip('#')
    named = {'white': 'FFFFFF', 'black': '000000', 'red': 'FF0000',
             'green': '008000', 'blue': '0000FF', 'yellow': 'FFFF00',
             'silver': 'C0C0C0', 'gray': '808080', 'grey': '808080'}
    if value.lower() in named:
        return named[value.lower()]
    if len(value) == 6:
        try:
            int(value, 16)
            return value.upper()
        except ValueError:
            return None
    return None


def _is_bare_mark(box) -> bool:
    """An empty paragraph: a paragraph mark with nothing drawn on it."""
    if not isinstance(box, ParaBox):
        return False
    if box.shading or box.borders or box.after_boxes or box.floats:
        return False
    for line in box.lines:
        if line.notes:
            return False
        for piece in line.pieces:
            if piece.text.strip() or piece.image is not None:
                return False
    return True


@dataclass
class Frame:
    """The area a column of body text flows into."""
    x: float
    top: float
    bottom: float
    width: float


class Flow:
    def __init__(self, layouter, options: Optional[dict] = None):
        self.lay = layouter
        self.doc: Document = layouter.doc
        self.options = options or {}
        self.pages: List[Page] = []
        self._page = None
        self._frames: List[Frame] = []
        self._frame_index = 0
        self._y = 0.0
        self._section: Optional[Section] = None
        self._page_number = 1
        self._section_index = 0
        self._note_boxes: dict = {}
        self._page_notes: List[tuple] = []
        self._notes_height = 0.0
        self._section_page_count = 0
        self._hf_cache: dict = {}
        self._section_top = True   # this frame opened a section
        self._carried_after = 0.0  # space-after left by the last section

    # ------------------------------------------------------------------
    def run(self) -> List[Page]:
        sections = self.doc.sections
        for index, section in enumerate(sections):
            self._section_index = index
            self._start_section(section, first=index == 0)
            boxes = self.lay.layout_blocks(section.blocks, self._frames[0].width)
            # The paragraph mark that carries a next-page section break does not
            # earn a page of its own: the following section starts a page anyway,
            # so Word lets an empty one hang past the bottom margin instead.
            following = sections[index + 1] if index + 1 < len(sections) else None
            loose_tail = (following is not None
                          and (following.break_type or 'nextPage') != 'continuous')
            self._place_boxes(boxes, loose_tail=loose_tail)
            tail = boxes[-1] if boxes else None
            self._carried_after = (tail.space_after
                                   if isinstance(tail, ParaBox) else 0.0)
        if self._page is None:
            self._new_page(self.doc.sections[0] if self.doc.sections else Section())
        self._finish_page()
        self._render_headers_footers()
        return self.pages

    # -- section / page management --------------------------------------
    def _start_section(self, section: Section, first: bool):
        self._section = section
        self._section_page_count = 0
        if section.page_num_start:
            self._page_number = section.page_num_start
        if first or self._page is None:
            self._new_page(section)
            self._section_top = True
            return
        break_type = section.break_type or 'nextPage'
        if break_type == 'continuous' and self._page is not None:
            # keep flowing on the current page, but recompute the frames
            self._frames = self._make_frames(section, self._page)
            self._frame_index = min(self._frame_index, len(self._frames) - 1)
            top = self._frames[self._frame_index].top
            self._y = max(self._y, top)
            return
        self._new_page(section)
        if break_type in ('evenPage', 'oddPage'):
            want_even = break_type == 'evenPage'
            if (self._page_number % 2 == 0) != want_even:
                self._new_page(section)
        # a paragraph at the start of a section keeps its space-before
        self._section_top = True

    def _make_frames(self, section: Section, page: Page) -> List[Frame]:
        header_h, footer_h = self._hf_heights(section, page)
        top = max(section.margin_top, section.header_distance + header_h)
        bottom = min(section.height - section.margin_bottom,
                     section.height - section.footer_distance - footer_h)
        if bottom <= top:
            bottom = min(section.height - 10.0, top + 20.0)
        x0 = section.margin_left + section.gutter
        frames = []
        for offset, width in section.column_layout():
            frames.append(Frame(x=x0 + offset, top=top, bottom=bottom, width=width))
        return frames

    def _new_page(self, section: Section):
        self._finish_page()
        page = Page(width=section.width, height=section.height,
                    number=self._page_number, section=section,
                    index=len(self.pages),
                    first_in_section=self._section_page_count == 0)
        self._section_page_count += 1
        self.pages.append(page)
        self._page = page
        self._page_number += 1
        self._frames = self._make_frames(section, page)
        self._frame_index = 0
        self._y = self._frames[0].top
        self._page_notes = []
        self._notes_height = 0.0
        if section.borders:
            self._emit_page_borders(page, section)

    def _finish_page(self):
        if self._page is None:
            return
        if self._page_notes:
            self._emit_notes(self._page)

    def _next_frame(self):
        """Move to the next column, or to a new page when columns run out."""
        if self._frame_index + 1 < len(self._frames):
            self._frame_index += 1
            self._y = self._frames[self._frame_index].top
            if self._section and self._section.column_separator:
                self._emit_column_separator()
        else:
            self._new_page(self._section)
        self._section_top = False

    @property
    def frame(self) -> Frame:
        return self._frames[self._frame_index]

    @property
    def _section_frame_top(self) -> bool:
        """Is this the first frame of a section (or of the document)?

        Word drops space-before at the top of a page or column - including one
        reached by a hard page break - but keeps it where a section starts.
        """
        return self._section_top

    def _space_before_at_section_top(self, box: ParaBox) -> float:
        """What is left of space-before where a section starts a new page.

        Word still collapses the gap across the break, and the space-after of
        the paragraph that ended the last section was already spent at the
        bottom of its page, so only the remainder shows at the top of this one.
        """
        if self.options.get('paragraph_spacing') == 'add':
            return box.space_before
        return max(0.0, box.space_before - self._carried_after)

    @property
    def _available(self) -> float:
        return self.frame.bottom - self._notes_height - self._y

    def _at_frame_top(self) -> bool:
        return abs(self._y - self.frame.top) < 0.01

    # -- headers and footers --------------------------------------------
    def _hf_for(self, section: Section, page_number: int, first_in_section: bool):
        even_odd = self.doc.settings.get('even_odd_headers')
        kind = 'default'
        if first_in_section and section.title_page and 'first' in section.headers:
            kind = 'first'
        elif even_odd and page_number % 2 == 0 and 'even' in section.headers:
            kind = 'even'
        header = section.headers.get(kind) or section.headers.get('default')
        kind_f = 'default'
        if first_in_section and section.title_page and 'first' in section.footers:
            kind_f = 'first'
        elif even_odd and page_number % 2 == 0 and 'even' in section.footers:
            kind_f = 'even'
        footer = section.footers.get(kind_f) or section.footers.get('default')
        return header, footer

    def _hf_heights(self, section: Section, page: Page):
        """Measured heights, so tall headers can push the body down."""
        key = (id(section), page.number % 2, page.first_in_section)
        cached = self._hf_cache.get(key)
        if cached is not None:
            return cached
        header, footer = self._hf_for(section, page.number, page.first_in_section)
        width = section.content_width
        header_h = self._blocks_height(header, width) if header else 0.0
        footer_h = self._blocks_height(footer, width) if footer else 0.0
        self._hf_cache[key] = (header_h, footer_h)
        return header_h, footer_h

    def _blocks_height(self, hf, width: float) -> float:
        boxes = self.lay.layout_blocks(hf.blocks, width)
        return sum(getattr(b, 'height', 0.0) for b in boxes)

    def _render_headers_footers(self):
        total = len(self.pages)
        self.lay._total_pages = total
        for page in self.pages:
            section = page.section
            if section is None:
                continue
            self.lay._page_number = page.number
            self.lay._page_num_format = section.page_num_format or 'decimal'
            header, footer = self._hf_for(section, page.number, page.first_in_section)
            width = section.content_width
            x = section.margin_left + section.gutter
            # Word paints the header and footer before the body, which is also
            # the order the two come out in when the PDF's text is extracted,
            # so they are emitted separately and moved to the front.
            body_ops, page.ops = page.ops, []
            if header is not None:
                boxes = self.lay.layout_blocks(header.blocks, width)
                y = section.header_distance
                for box in boxes:
                    y = self._emit_box(page, box, x, y, width)
            if footer is not None:
                boxes = self.lay.layout_blocks(footer.blocks, width)
                height = sum(getattr(b, 'height', 0.0) for b in boxes)
                y = section.height - section.footer_distance - height
                for box in boxes:
                    y = self._emit_box(page, box, x, y, width)
            page.ops.extend(body_ops)

    # -- placing --------------------------------------------------------
    def _place_boxes(self, boxes: List[object], loose_tail: bool = False):
        index = 0
        while index < len(boxes):
            box = boxes[index]
            if isinstance(box, ParaBox) and box.keep_next:
                self._handle_keep_group(boxes, index)
            if isinstance(box, ParaBox):
                last = index == len(boxes) - 1
                self._place_paragraph(box, overflow=(loose_tail and last
                                                     and _is_bare_mark(box)))
            elif isinstance(box, TableBox):
                if box.page_break_before and not self._at_frame_top():
                    self._next_frame()
                self._place_table(box)
            index += 1

    def _handle_keep_group(self, boxes, index):
        """Break early when a keep-next run cannot fit where it stands.

        Word only requires the kept paragraphs plus the first line of what
        follows; trailing space is allowed to run past the bottom margin.
        """
        needed = 0.0
        i = index
        while i < len(boxes):
            box = boxes[i]
            if isinstance(box, ParaBox):
                needed += box.space_before + box.pad_top
                if box.keep_next:
                    lines = box.lines if box.keep_lines else box.lines[:2]
                    needed += sum(l.height for l in lines)
                else:
                    needed += box.lines[0].height if box.lines else 0.0
                    break
            elif isinstance(box, TableBox):
                needed += box.rows[0].height if box.rows else 0.0
                break
            else:
                break
            i += 1
        if needed > self._available and not self._at_frame_top() \
                and needed <= self.frame.bottom - self.frame.top:
            self._next_frame()

    def _place_paragraph(self, box: ParaBox, overflow: bool = False):
        if box.page_break_before and not self._at_frame_top():
            self._next_frame()
        if overflow and not box.page_break_before \
                and box.height > self._available:
            # nothing follows it on this page, so leave it where it stands
            self._emit_box(self._page, box, self.frame.x, self._y,
                           self.frame.width)
            return
        lines = box.lines
        start = 0
        first_fragment = True
        space_before = box.space_before
        while start < len(lines) or (first_fragment and not lines):
            if first_fragment:
                # Word drops space-before at the top of a page or column
                if not self._at_frame_top():
                    space_before = box.space_before
                elif self._section_frame_top:
                    space_before = self._space_before_at_section_top(box)
                else:
                    space_before = 0.0
            avail = self._available - (space_before + box.pad_top
                                       if first_fragment else 0.0)
            count, hard_break = self._fit_lines(lines, start, avail, box,
                                                first_fragment)
            if count == 0:
                if self._at_frame_top():
                    count = max(1, self._fit_lines(lines, start, avail, box,
                                                   first_fragment, force=True)[0])
                else:
                    self._next_frame()
                    continue
            fragment_lines = lines[start:start + count]
            notes = [n for line in fragment_lines for n in line.notes]
            if notes:
                self._reserve_notes(notes)
            fragment = replace(box, lines=fragment_lines,
                               space_before=space_before if first_fragment else 0.0,
                               space_after=(box.space_after
                                            if start + count >= len(lines) else 0.0),
                               open_top=first_fragment,
                               open_bottom=start + count >= len(lines),
                               after_boxes=[])
            self._y = self._emit_box(self._page, fragment, self.frame.x, self._y,
                                     self.frame.width)
            start += count
            first_fragment = False
            if hard_break:
                self._next_frame()
            elif start < len(lines):
                self._next_frame()
            if not lines:
                break

    def _fit_lines(self, lines, start, avail, box: ParaBox, first_fragment,
                   force=False):
        """How many lines fit; honours keep-lines, widows and hard breaks."""
        if start >= len(lines):
            return 0, False
        used = 0.0
        count = 0
        hard_break = False
        for i in range(start, len(lines)):
            line = lines[i]
            if used + line.height > avail + 0.01 and not force:
                break
            used += line.height
            count += 1
            if line.page_break:
                hard_break = True
                break
        if hard_break:
            return count, True
        if count >= len(lines) - start:
            return count, False
        if force:
            return max(1, count), False
        if box.keep_lines:
            return 0, False
        remaining = len(lines) - start - count
        if box.widow_control:
            if count == 1 and len(lines) - start >= 2:
                return 0, False
            if remaining == 1 and count >= 2:
                count -= 1
        return count, False

    def _place_table(self, box: TableBox):
        rows = list(box.rows)
        header_rows = box.repeat_header
        index = 0
        repeat = []
        while index < len(rows):
            row = rows[index]
            needed = row.height
            if not self._at_frame_top() and needed > self._available:
                self._next_frame()
                repeat = header_rows
                continue
            if repeat and index > 0:
                for head in repeat:
                    if head.height <= self._available:
                        self._y = self._emit_row(self._page, box, head,
                                                 self.frame.x, self._y,
                                                 box.rows.index(head))
                repeat = []
            if needed > self._available and self._at_frame_top():
                # a row taller than a whole page: draw it and let it run over
                self._y = self._emit_row(self._page, box, row, self.frame.x,
                                         self._y, index)
                index += 1
                continue
            if needed > self._available:
                self._next_frame()
                repeat = header_rows
                continue
            self._y = self._emit_row(self._page, box, row, self.frame.x,
                                     self._y, index)
            index += 1

    # -- footnotes -------------------------------------------------------
    def _reserve_notes(self, keys):
        for key in keys:
            if key in [k for k, _ in self._page_notes]:
                continue
            boxes = self._note_layout(key)
            height = sum(getattr(b, 'height', 0.0) for b in boxes)
            if not self._page_notes:
                height += SEPARATOR_GAP * 2
            self._page_notes.append((key, boxes))
            self._notes_height += height

    def _note_layout(self, key):
        cached = self._note_boxes.get(key)
        if cached is not None:
            return cached
        mark, blocks = self.lay._notes[key]
        self.lay._note_mark = mark
        boxes = self.lay.layout_blocks(blocks, self.frame.width)
        self._note_boxes[key] = boxes
        return boxes

    def _emit_notes(self, page: Page):
        if not self._page_notes:
            return
        height = self._notes_height - SEPARATOR_GAP * 2
        frame = self._frames[0]
        y = frame.bottom - height
        page.ops.append(LineOp(x1=frame.x, y1=y - SEPARATOR_GAP,
                               x2=frame.x + min(frame.width, 144.0),
                               y2=y - SEPARATOR_GAP, color='000000', width=0.5))
        for _key, boxes in self._page_notes:
            for box in boxes:
                y = self._emit_box(page, box, frame.x, y, frame.width)

    # ------------------------------------------------------------------
    # emission
    # ------------------------------------------------------------------
    def _emit_box(self, page: Page, box, x: float, y: float, width: float) -> float:
        if isinstance(box, ParaBox):
            return self._emit_paragraph(page, box, x, y, width)
        if isinstance(box, TableBox):
            for row_index, row in enumerate(box.rows):
                y = self._emit_row(page, box, row, x, y, row_index)
            return y
        return y + getattr(box, 'height', 0.0)

    def _emit_paragraph(self, page: Page, box: ParaBox, x: float, y: float,
                        width: float) -> float:
        top = y + box.space_before + (box.pad_top if box.open_top else 0.0)
        content_height = sum(l.height for l in box.lines)
        left = x + box.left
        right = x + max(box.left, width - box.right)
        if box.shading:
            page.ops.append(RectOp(x=left, y=top, w=max(0.0, right - left),
                                   h=content_height, fill=box.shading))
        if box.borders:
            self._emit_borders(page, box.borders, left, top, right - left,
                               content_height, box.open_top, box.open_bottom)
        if box.bookmarks:
            for name in box.bookmarks:
                page.ops.append(DestOp(name=name, x=left, y=top))
        if box.outline_level is not None and box.title and box.open_top:
            page.ops.append(OutlineOp(title=box.title, level=box.outline_level, y=top))
        if box.floats and box.open_top:
            for obj, boxes in box.floats:
                self._emit_float(page, obj, boxes, x, width, top)
        cursor = top
        for line in box.lines:
            baseline = cursor + line.ascent
            self._emit_line(page, line, x, baseline)
            cursor += line.height
        return (top + content_height + box.space_after
                + (box.pad_bottom if box.open_bottom else 0.0))

    # -- floating (anchored) objects -------------------------------------
    def _emit_float(self, page: Page, obj, boxes, column_x: float,
                    column_width: float, para_top: float):
        section = page.section or Section()
        width = obj.width or column_width
        height = obj.height or 0.0
        x = self._float_x(obj, section, column_x, column_width, width)
        y = self._float_y(obj, section, para_top, height)
        ops: List[object] = []
        if obj.fill or obj.stroke:
            ops.append(RectOp(x=x, y=y, w=width, h=height,
                              fill=_hex(obj.fill), stroke=_hex(obj.stroke),
                              line_width=obj.stroke_width or (0.75 if obj.stroke else 0.0)))
        if obj.image is not None and obj.image.data:
            ops.append(ImageOp(x=x, y=y, w=width, h=height, data=obj.image.data,
                               fmt=obj.image.fmt, rotation=obj.rotation,
                               crop=obj.image.crop))
        if boxes:
            inner_x = x + 3.6
            inner_y = y + 1.8
            inner_w = max(1.0, width - 7.2)
            saved = page.ops
            page.ops = ops
            try:
                for inner in boxes:
                    inner_y = self._emit_box(page, inner, inner_x, inner_y, inner_w)
            finally:
                page.ops = saved
        if not ops:
            return
        if obj.behind:
            page.ops[0:0] = ops
        else:
            page.ops.extend(ops)

    @staticmethod
    def _float_x(obj, section: Section, column_x: float, column_width: float,
                 width: float) -> float:
        rel = obj.h_relative or 'column'
        if rel == 'page':
            base, extent = 0.0, section.width
        elif rel in ('margin', 'insideMargin', 'outsideMargin'):
            base, extent = section.margin_left, section.content_width
        elif rel == 'leftMargin':
            base, extent = 0.0, section.margin_left
        elif rel == 'rightMargin':
            base = section.width - section.margin_right
            extent = section.margin_right
        else:                       # column, character, text
            base, extent = column_x, column_width
        align = (obj.h_align or '').lower()
        if align in ('center', 'centre'):
            return base + max(0.0, (extent - width) / 2.0)
        if align in ('right', 'outside'):
            return base + max(0.0, extent - width)
        if align in ('left', 'inside'):
            return base
        return base + obj.h_offset

    @staticmethod
    def _float_y(obj, section: Section, para_top: float, height: float) -> float:
        rel = obj.v_relative or 'paragraph'
        if rel == 'page':
            base, extent = 0.0, section.height
        elif rel == 'margin':
            base, extent = section.margin_top, section.content_height
        elif rel == 'topMargin':
            base, extent = 0.0, section.margin_top
        elif rel == 'bottomMargin':
            base = section.height - section.margin_bottom
            extent = section.margin_bottom
        else:                       # paragraph, line, text
            base, extent = para_top, 0.0
        align = (obj.v_align or '').lower()
        if align == 'center':
            return base + max(0.0, (extent - height) / 2.0)
        if align == 'bottom':
            return base + max(0.0, extent - height)
        if align == 'top':
            return base
        return base + obj.v_offset

    @staticmethod
    def _merge_pieces(pieces):
        """Join neighbouring pieces that share a style into one draw call.

        A line is measured word by word, but drawing it word by word would
        triple the size of the content stream for no visible difference.
        """
        out = []
        for piece in pieces:
            if out:
                last = out[-1]
                if (last.image is None and piece.image is None
                        and last.font is piece.font
                        and last.size == piece.size
                        and last.color == piece.color
                        and last.rise == piece.rise
                        and last.char_space == piece.char_space
                        and last.scale == piece.scale
                        and last.underline == piece.underline
                        and last.underline_color == piece.underline_color
                        and last.strike == piece.strike
                        and last.dstrike == piece.dstrike
                        and last.highlight == piece.highlight
                        and last.shade == piece.shade
                        and last.link is piece.link
                        and piece.note is None
                        and not last.leader and not piece.leader
                        and abs(last.x + last.width - piece.x) < 0.02):
                    out[-1] = replace(last, text=last.text + piece.text,
                                      width=last.width + piece.width)
                    continue
            out.append(piece)
        return out

    def _emit_line(self, page: Page, line: LineBox, x: float, baseline: float):
        for piece in self._merge_pieces(line.pieces):
            px = x + piece.x
            if piece.image is not None:
                page.ops.append(ImageOp(x=px, y=baseline - piece.height,
                                        w=piece.width, h=piece.height,
                                        data=piece.image.data, fmt=piece.image.fmt,
                                        rotation=piece.image.rotation,
                                        crop=piece.image.crop))
                if piece.link is not None:
                    page.ops.append(LinkOp(x=px, y=baseline - piece.height,
                                           w=piece.width, h=piece.height,
                                           url=piece.link.url,
                                           anchor=piece.link.anchor))
                continue
            if not piece.text:
                continue
            font = piece.font
            info = font.info if font else None
            top = baseline - piece.rise - (info.win_ascent if info else 0.9) * piece.size
            bottom = baseline - piece.rise + (info.win_descent if info else 0.25) * piece.size
            fill = piece.highlight or piece.shade
            if fill:
                page.ops.append(RectOp(x=px, y=top, w=piece.width, h=bottom - top,
                                       fill=fill))
            # Drawn at the measuring size: Word draws a hair larger (it snaps
            # to the device grid) but advances by the nominal size, and keeping
            # the two equal is what lets whole runs be drawn in one go.
            page.ops.append(TextOp(x=px, y=baseline - piece.rise, text=piece.text,
                                   font=font.name if font else 'Helvetica',
                                   size=piece.measure or piece.size,
                                   color=piece.color,
                                   char_space=piece.char_space,
                                   faux_bold=bool(font and font.faux_bold),
                                   faux_italic=bool(font and font.faux_italic),
                                   scale=piece.scale))
            if piece.underline:
                thickness = max(0.4, piece.size * 0.055)
                uy = baseline - piece.rise + max(1.0, piece.size * 0.11)
                color = (piece.underline_color or piece.color)
                dash = (1, 2) if piece.underline in ('dotted', 'dottedHeavy') else None
                if piece.underline in ('dash', 'dashed', 'dashedHeavy'):
                    dash = (3, 2)
                count = 2 if piece.underline in ('double',) else 1
                for i in range(count):
                    offset = uy + i * thickness * 2
                    page.ops.append(LineOp(x1=px, y1=offset, x2=px + piece.width,
                                           y2=offset, color=color, width=thickness,
                                           dash=dash))
            if piece.strike or piece.dstrike:
                thickness = max(0.4, piece.size * 0.05)
                base = baseline - piece.rise - piece.size * 0.26
                offsets = [base] if piece.strike and not piece.dstrike else \
                    [base - thickness, base + thickness]
                for offset in offsets:
                    page.ops.append(LineOp(x1=px, y1=offset, x2=px + piece.width,
                                           y2=offset, color=piece.color,
                                           width=thickness))
            if piece.link is not None:
                page.ops.append(LinkOp(x=px, y=top, w=piece.width, h=bottom - top,
                                       url=piece.link.url, anchor=piece.link.anchor))

    def _emit_row(self, page: Page, table: TableBox, row: RowBox, x: float,
                  y: float, row_index: int = 0) -> float:
        base_x = x + table.x
        for cell in row.cells:
            if cell.v_merge == 'continue':
                continue
            height = row.height
            if cell.span_rows > 1:
                height = sum(r.height for r in
                             table.rows[row_index:row_index + cell.span_rows])
            cell_x = base_x + cell.x
            if cell.shading:
                page.ops.append(RectOp(x=cell_x, y=y, w=cell.width, h=height,
                                       fill=cell.shading))
        for cell in row.cells:
            if cell.v_merge == 'continue':
                continue
            height = row.height
            if cell.span_rows > 1:
                height = sum(r.height for r in
                             table.rows[row_index:row_index + cell.span_rows])
            cell_x = base_x + cell.x
            inner_x = cell_x + cell.margins.get('left', 5.4)
            inner_width = max(1.0, cell.width - cell.margins.get('left', 5.4)
                              - cell.margins.get('right', 5.4))
            content = cell.content_height
            free = height - content - cell.margins.get('top', 0.0) \
                - cell.margins.get('bottom', 0.0)
            offset = 0.0
            if cell.v_align == 'center':
                offset = max(0.0, free / 2.0)
            elif cell.v_align == 'bottom':
                offset = max(0.0, free)
            cursor = y + row.border_top + cell.margins.get('top', 0.0) + offset
            for box in cell.boxes:
                cursor = self._emit_box(page, box, inner_x, cursor, inner_width)
        for cell in row.cells:
            if cell.v_merge == 'continue':
                continue
            height = row.height
            if cell.span_rows > 1:
                height = sum(r.height for r in
                             table.rows[row_index:row_index + cell.span_rows])
            if cell.borders:
                self._emit_borders(page, cell.borders, base_x + cell.x, y,
                                   cell.width, height, True, True)
        return y + row.height

    def _emit_borders(self, page: Page, borders: dict, x: float, y: float,
                      width: float, height: float, open_top: bool, open_bottom: bool):
        styles = self.doc.styles if self.doc else None
        # Each border sits its own "space" away from the text, so the box only
        # closes if every line is extended to its neighbours' offsets.
        spaces = {}
        for side in ('top', 'bottom', 'left', 'right'):
            border = borders.get(side)
            spaces[side] = (border.space or 0.0) if (
                border is not None and border.visible) else 0.0
        for side in ('top', 'bottom', 'left', 'right'):
            border = borders.get(side)
            if border is None or not border.visible:
                continue
            if side == 'top' and not open_top:
                continue
            if side == 'bottom' and not open_bottom:
                continue
            color = (styles.resolve_border_color(border) if styles
                     else border.color) or '000000'
            thickness = max(0.25, border.size or 0.5)
            dash = BORDER_DASHES.get(border.style or '')
            left = x - spaces['left']
            right = x + width + spaces['right']
            top = y - spaces['top']
            bottom = y + height + spaces['bottom']
            if side == 'top':
                page.ops.append(LineOp(x1=left, y1=top, x2=right, y2=top,
                                       color=color, width=thickness, dash=dash))
            elif side == 'bottom':
                page.ops.append(LineOp(x1=left, y1=bottom, x2=right, y2=bottom,
                                       color=color, width=thickness, dash=dash))
            elif side == 'left':
                page.ops.append(LineOp(x1=left, y1=top, x2=left, y2=bottom,
                                       color=color, width=thickness, dash=dash))
            else:
                page.ops.append(LineOp(x1=right, y1=top, x2=right, y2=bottom,
                                       color=color, width=thickness, dash=dash))
            if border.style == 'double':
                gap = thickness + 1.0
                if side in ('top', 'bottom'):
                    yy = (top - gap) if side == 'top' else (bottom + gap)
                    page.ops.append(LineOp(x1=left, y1=yy, x2=right, y2=yy,
                                           color=color, width=thickness))
                else:
                    xx = (left - gap) if side == 'left' else (right + gap)
                    page.ops.append(LineOp(x1=xx, y1=top, x2=xx, y2=bottom,
                                           color=color, width=thickness))

    def _emit_page_borders(self, page: Page, section: Section):
        borders = section.borders or {}
        x = section.margin_left * 0.5
        y = section.margin_top * 0.5
        width = section.width - section.margin_left * 0.5 - section.margin_right * 0.5
        height = section.height - section.margin_top * 0.5 - section.margin_bottom * 0.5
        self._emit_borders(page, borders, x, y, width, height, True, True)

    def _emit_column_separator(self):
        frame = self._frames[self._frame_index]
        previous = self._frames[self._frame_index - 1]
        x = (previous.x + previous.width + frame.x) / 2.0
        self._page.ops.append(LineOp(x1=x, y1=frame.top, x2=x, y2=frame.bottom,
                                     color='808080', width=0.5))
